sys_script_fix.script:
var gr = new GlideRecord('apm_metric');
gr.addQuery('ci_class','cmdb_ci_business_capability');
gr.query();
while (gr.next()){
	if (gr.asmt_metric_type){
		var assmntTypeSysId = gr.getValue('asmt_metric_type');
		var grAssmntType = new GlideRecord('asmt_metric_type');
		if (grAssmntType.get(assmntTypeSysId)){
			grAssmntType.setValue('condition','sys_class_name=cmdb_ci_business_capability^leaf_node=true^EQ');
			grAssmntType.update();
		}
	}
	if (gr.asmt_metric_category){
		var assmntCatSysId = gr.getValue('asmt_metric_category');
		var grAssmntCat = new GlideRecord('asmt_metric_category');
		if (grAssmntCat.get(assmntCatSysId)){
			grAssmntCat.setValue('filter','');
			grAssmntCat.update();
		}		
	}
}
